from collections import defaultdict


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members: list[str] = list(members)
        self._members_set: set[str] = set(members)
        # Store balances internally in integer cents to avoid floating-point issues
        self._balances_cents: dict[str, int] = {m: 0 for m in self.members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Amount must be strictly positive.")

        if payer not in self._members_set:
            raise ValueError(f"Payer '{payer}' is not a member of the group.")

        if participants is None:
            participants = list(self.members)
        else:
            participants = list(participants)

        if not participants:
            raise ValueError("Participants list cannot be empty.")

        for p in participants:
            if p not in self._members_set:
                raise ValueError(f"Participant '{p}' is not a member of the group.")

        total_cents = round(amount * 100)
        n = len(participants)

        # Requirement 2:
        # Every other participant owes exactly the amount rounded down to the cent.
        # Leftover cents are borne by the payer.
        base_share_cents = total_cents // n

        # If payer is among participants:
        # Others pay base_share_cents. Payer's share is total_cents - (n - 1) * base_share_cents.
        # Payer gets total_cents - payer's share = (n - 1) * base_share_cents.
        # Each other participant owes base_share_cents.
        #
        # If payer is NOT among participants:
        # All n participants are "other participants", so each owes base_share_cents.
        # Payer paid total_cents, receives n * base_share_cents from them,
        # so payer absorbs total_cents - n * base_share_cents.
        # Thus payer gets + n * base_share_cents net.
        if payer in participants:
            for p in participants:
                if p != payer:
                    self._balances_cents[p] -= base_share_cents
                    self._balances_cents[payer] += base_share_cents
        else:
            for p in participants:
                self._balances_cents[p] -= base_share_cents
                self._balances_cents[payer] += base_share_cents

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {m: self._balances_cents[m] / 100.0 for m in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Debtors have negative balance; creditors have positive balance.
        debtors: list[list] = []
        creditors: list[list] = []

        for m in self.members:
            cents = self._balances_cents[m]
            if cents < 0:
                debtors.append([m, -cents])
            elif cents > 0:
                creditors.append([m, cents])

        transactions: list[tuple[str, str, float]] = []

        i = 0
        j = 0
        while i < len(debtors) and j < len(creditors):
            debtor_name, debt_amt = debtors[i]
            creditor_name, cred_amt = creditors[j]

            settle_amt = min(debt_amt, cred_amt)
            transactions.append((debtor_name, creditor_name, settle_amt / 100.0))

            debtors[i][1] -= settle_amt
            creditors[j][1] -= settle_amt

            if debtors[i][1] == 0:
                i += 1
            if creditors[j][1] == 0:
                j += 1

        return transactions
